package android.graphics; public class Rect { public int left,top,right,bottom; public Rect(){} public Rect(int l,int t,int r,int b){set(l,t,r,b);} public void set(int l,int t,int r,int b){left=l;top=t;right=r;bottom=b;} public boolean contains(int x,int y){return x>=left&&x<right&&y>=top&&y<bottom;} public boolean isEmpty(){return right<=left||bottom<=top;} public void offset(int x,int y){left+=x;right+=x;top+=y;bottom+=y;} public void union(Rect r){left=Math.min(left,r.left);top=Math.min(top,r.top);right=Math.max(right,r.right);bottom=Math.max(bottom,r.bottom);} }
